def rec(a, b):
	ans = 0
	while True:
		if a == b:
			ans += 1
			break
		elif a == 0 or b == 0:
			break
		if a > b:
			k = (a - a % b) // b
			(a, b) = (a % b, b)
		elif a < b:
			k = (b - b % a) // a
			(a, b) = (a, b % a)
		ans += k
	return ans

